```typescript
/**
 * @license
 * SPDX-License-Identifier: Apache-2.0
 */
import fs from 'fs';
import { Client } from 'pg';

interface SeedData {
  topics: any[];
  drafts: any[];
  auditLogs: any[];
}

export async function executeDataBackfilling(databaseJsonPath: string, postgresConnString: string) {
